var i=`test-driven-development-tdd`;var n=82;var o={en:[{id:`T082-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Static analysis inspects source or compiled representations without executing full application behavior.`},{id:`B`,text:`Mutation testing changes code in small controlled ways and checks whether the test suite detects those changes.`},{id:`C`,text:`TDD follows a short red-green-refactor loop: write a failing test, implement the minimal behavior, then improve design without changing behavior.`},{id:`D`,text:`Code smells are symptoms of possible design problems, not automatic proof that code is wrong.`}]},{id:`T082-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Record debt with business impact, risk, affected modules, approximate remediation cost and triggers.`},{id:`B`,text:`Use consumer-driven contracts or shared schemas with executable verification.`},{id:`C`,text:`Choose unit tests for isolated rules, integration tests for storage and service boundaries, and E2E tests for critical user journeys.`},{id:`D`,text:`Start from observable behavior and small testable increments, keeping tests independent of private implementation details.`}]},{id:`T082-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Given a paid reservation inside the free-cancellation window, when the guest cancels, then refund eligibility is recorded and inventory becomes available according to policy.`},{id:`B`,text:`A 300-line booking controller may contain validation, pricing and persistence. Extract coherent policies and retain a thin orchestrator, confirming the same responses and side effects.`},{id:`C`,text:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`},{id:`D`,text:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`}]},{id:`T082-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Excessive mocks can test a fictional system, while broad E2E tests are slow and flaky.`},{id:`B`,text:`TDD does not prove requirements are correct or replace exploratory testing.`},{id:`C`,text:`A large number of mocked unit tests may miss broken integration behavior.`},{id:`D`,text:`Matching JSON shapes alone misses semantics, authorization and performance.`}]},{id:`T082-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It can clarify interfaces before implementation.`}]}]},{id:`T082-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`TDD means writing exhaustive implementation code before the first test.`}]}]},{id:`T082-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`A test written to match an AI-generated implementation after the fact is not truly test-first.`}]}]},{id:`T082-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Static analysis can prove every runtime business rule is implemented correctly.`},{id:`B`,text:`TDD follows a short red-green-refactor loop: write a failing test, implement the minimal behavior, then improve design without changing behavior.`},{id:`C`,text:`Start from observable behavior and small testable increments, keeping tests independent of private implementation details.`},{id:`D`,text:`A red test may be skipped when AI has already described the intended feature.`}]},{id:`T082-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A contract test can replace all system-level integration tests in a deployment.`},{id:`B`,text:`TDD means writing exhaustive implementation code before the first test.`},{id:`C`,text:`A test written to match an AI-generated implementation after the fact is not truly test-first.`},{id:`D`,text:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`}]},{id:`T082-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Give an agent acceptance examples one at a time and require a visible failing-test-first sequence, minimal implementation and refactor for each discount rule.`},{id:`B`,text:`Ask an agent to create a consumer contract for booking cancellation, including a 409 error and optional new fields, then verify two server versions.`},{id:`C`,text:`Ask an agent for one meaningful test at each layer for reservation confirmation. Explain which failures each catches and which remain uncovered.`},{id:`D`,text:`Ask an agent to build a testing plan for a checkout workflow, map each requirement to the cheapest effective test layer and quantify expected runtime.`}]},{id:`T082-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How would your test suite expose an incorrect assumption shared by the developer and the AI?`}]}]},{id:`T082-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T082-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`,b:!0},{t:` — propose three checks for `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T082-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T082-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Test-Driven Development (TDD)`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T082-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Розробка через тести (TDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Статичний аналіз перевіряє код або проміжне представлення без повного виконання застосунку.`},{id:`B`,text:`Мутаційне тестування вносить невеликі контрольовані зміни до коду й перевіряє, чи виявляють їх тести.`},{id:`C`,text:`TDD працює коротким циклом red-green-refactor: спершу тест, який падає, далі мінімальна реалізація, потім покращення дизайну без зміни поведінки.`},{id:`D`,text:`Code smells — сигнали можливих проблем дизайну, а не доказ помилки.`}]},{id:`T082-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Розробка через тести (TDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Фіксуйте борг із бізнесовим впливом, ризиком, модулями, приблизною ціною виправлення й тригерами.`},{id:`B`,text:`Використовуйте consumer-driven контракти або спільні схеми з виконуваною перевіркою.`},{id:`C`,text:`Використовуйте unit-тести для окремих правил, інтеграційні — для БД та сервісних меж, E2E — для ключових шляхів користувача.`},{id:`D`,text:`Починайте зі спостережуваної поведінки та малих кроків, не прив’язуючи тести до внутрішніх деталей.`}]},{id:`T082-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Розробка через тести (TDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`За умови оплаченого бронювання в період безкоштовного скасування, коли гість скасовує його, право на повернення коштів фіксується, а номер стає доступним за правилами.`},{id:`B`,text:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження. Винесіть узгоджені правила та залиште тонкий оркестратор, перевіривши незмінність відповідей і побічних ефектів.`},{id:`C`,text:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`},{id:`D`,text:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`}]},{id:`T082-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Розробка через тести (TDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Надмірні mocks тестують вигадану систему, а широкі E2E повільні й нестабільні.`},{id:`B`,text:`TDD не доводить правильність вимог і не замінює дослідницьке тестування.`},{id:`C`,text:`Велика кількість unit-тестів із mocks може пропустити поламані інтеграції.`},{id:`D`,text:`Збіг JSON-схеми не гарантує семантику, авторизацію чи швидкість.`}]},{id:`T082-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Метод допомагає прояснити контракт до коду.`}]}]},{id:`T082-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`TDD означає написати всю реалізацію до першого тесту.`}]}]},{id:`T082-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Тест, написаний під уже згенеровану ШІ реалізацію, не є test-first.`}]}]},{id:`T082-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Розробка через тести (TDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Статичний аналіз доводить коректність усіх бізнес-правил під час виконання.`},{id:`B`,text:`TDD працює коротким циклом red-green-refactor: спершу тест, який падає, далі мінімальна реалізація, потім покращення дизайну без зміни поведінки.`},{id:`C`,text:`Починайте зі спостережуваної поведінки та малих кроків, не прив’язуючи тести до внутрішніх деталей.`},{id:`D`,text:`Падаючий тест можна пропустити, якщо ШІ вже описав функцію.`}]},{id:`T082-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Розробка через тести (TDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Контрактний тест може замінити всі інтеграційні тести системи.`},{id:`B`,text:`TDD означає написати всю реалізацію до першого тесту.`},{id:`C`,text:`Тест, написаний під уже згенеровану ШІ реалізацію, не є test-first.`},{id:`D`,text:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`}]},{id:`T082-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Давайте агенту приймальні приклади по одному й вимагайте спочатку падаючий тест, мінімальну реалізацію та рефакторинг кожного правила.`},{id:`B`,text:`Попросіть агента створити споживчий контракт скасування бронювання, включно з 409 та новими необов’язковими полями, і перевірити дві версії сервера.`},{id:`C`,text:`Попросіть агента зробити по одному змістовному тесту кожного рівня для підтвердження бронювання. Поясніть, які збої вони ловлять, а які ні.`},{id:`D`,text:`Попросіть агента скласти план тестів checkout, зіставити вимоги з найдешевшим ефективним рівнем і оцінити час прогону.`}]},{id:`T082-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як тести покажуть помилкове припущення, спільне для розробника й ШІ?`}]}]},{id:`T082-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Розробка через тести (TDD)`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T082-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Розробка через тести (TDD)`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T082-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T082-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Розробка через тести (TDD)`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:82,questions:o};export{s as default,o as questions,i as slug,n as topicId};